-- Dados de demonstração do dashboard de vendas (Power BI), gerados da planilha RV_Label_Base_PowerBI.xlsx:
-- 489 pedidos (724 itens) de out/2025 a set/2026, 110 clientes, 3 vendedoras, metas e estoque mensais.
-- Tudo entra com simulado = 1: a API, o site e o painel da loja não mostram nem reaproveitam essas linhas.
--
-- Rodar depois do `npm run migrar` (precisa das migrações 002 e 003) e com o catálogo no banco (`npm run seed`):
--   mysql --default-character-set=utf8mb4 -u root -p Rv_Label < docs/powerbi/dados-simulados.sql
-- Rodar de novo apaga os simulados e carrega outra vez. Nada real é apagado ou alterado, exceto produto.custo,
-- que é preenchido só nas peças que ainda não tinham custo.
--
-- Peça = produto + cor (a planilha não tinha tamanho): cada item ganha um tamanho que a cor tem (P 30%, M 40%, G 30%),
-- só para apontar para uma variação existente. Telefones simulados começam com 0000 e não existem.
SET NAMES utf8mb4;
START TRANSACTION;

DELETE FROM pedido WHERE simulado = 1;  -- os itens saem junto (ON DELETE CASCADE)
DELETE FROM cliente WHERE simulado = 1;
DELETE FROM vendedor WHERE simulado = 1;
DELETE FROM meta_mensal WHERE simulado = 1;
DELETE FROM estoque_mensal WHERE simulado = 1;

-- Custo das peças (só onde ainda não havia).
UPDATE produto SET custo = 36.70 WHERE codigo = 'essence-004' AND custo IS NULL;
UPDATE produto SET custo = 30.85 WHERE codigo = 'essence-005' AND custo IS NULL;
UPDATE produto SET custo = 51.92 WHERE codigo = 'essence-006' AND custo IS NULL;
UPDATE produto SET custo = 27.41 WHERE codigo = 'essence-007' AND custo IS NULL;
UPDATE produto SET custo = 30.92 WHERE codigo = 'essence-008' AND custo IS NULL;
UPDATE produto SET custo = 30.89 WHERE codigo = 'essence-009' AND custo IS NULL;
UPDATE produto SET custo = 32.39 WHERE codigo = 'essence-010' AND custo IS NULL;
UPDATE produto SET custo = 21.66 WHERE codigo = 'essence-011' AND custo IS NULL;
UPDATE produto SET custo = 19.08 WHERE codigo = 'essence-012' AND custo IS NULL;
UPDATE produto SET custo = 21.84 WHERE codigo = 'essence-013' AND custo IS NULL;
UPDATE produto SET custo = 21.92 WHERE codigo = 'essence-014' AND custo IS NULL;
UPDATE produto SET custo = 18.63 WHERE codigo = 'essence-015' AND custo IS NULL;
UPDATE produto SET custo = 23.55 WHERE codigo = 'essence-016' AND custo IS NULL;
UPDATE produto SET custo = 27.38 WHERE codigo = 'essence-017' AND custo IS NULL;
UPDATE produto SET custo = 14.33 WHERE codigo = 'essence-018' AND custo IS NULL;

-- Peças: produto, cor e um tamanho existente para cada faixa (P/M/G; sem ele, o que a cor tiver).
SET @tP = (SELECT id_tamanho FROM tamanho WHERE nome = 'P');
SET @tM = (SELECT id_tamanho FROM tamanho WHERE nome = 'M');
SET @tG = (SELECT id_tamanho FROM tamanho WHERE nome = 'G');
SET @P001 = (SELECT id_produto FROM produto WHERE codigo = 'essence-004'), @P001c = (SELECT id_cor FROM cor WHERE nome = 'Cinza');
SET @P001P = COALESCE((SELECT id_tamanho FROM variacao WHERE id_produto = @P001 AND id_cor = @P001c AND id_tamanho = @tP), (SELECT MIN(id_tamanho) FROM variacao WHERE id_produto = @P001 AND id_cor = @P001c));
SET @P001M = COALESCE((SELECT id_tamanho FROM variacao WHERE id_produto = @P001 AND id_cor = @P001c AND id_tamanho = @tM), (SELECT MIN(id_tamanho) FROM variacao WHERE id_produto = @P001 AND id_cor = @P001c));
